mapper.update:
update COLLECT_NETWORK_CARD
set STATUS = #{status}
where ASSET_ID = #{assetId}
  and IP = #{ip}
  and STATUS = #{seachStatus}

mapper.select:
SELECT *
FROM COLLECT_NETWORK_CARD b
WHERE b.COLLECT_CODE = (
	SELECT MAX(to_number(COLLECT_CODE)) AS code
	FROM COLLECT_NETWORK_CARD
	WHERE IP = #{ip}
)
  AND ip = #{ip}

SELECT *
FROM COLLECT_NETWORK_CARD b
WHERE b.COLLECT_CODE = (
	SELECT MAX(TO_NUMBER(COLLECT_CODE)) AS code
	FROM COLLECT_NETWORK_CARD
	WHERE MAC_ADDRESS = #{atPhysAddress}
	  AND ASSET_ID = #{assetId}
)

SELECT *
FROM COLLECT_NETWORK_CARD b
WHERE b.id = (
	SELECT MAX(id) AS code
	FROM COLLECT_NETWORK_CARD
	WHERE NAME = #{networkName}
	  AND ASSET_ID = #{assetId}
)
